using System;
using System.IO;
using System.IO.Compression;
using System.Reflection;
using System.Diagnostics;
using System.Windows.Forms;
using System.Drawing;
using System.Threading.Tasks;
class Setup {
 static string Q(string s){return "\""+s.Replace("\"","\\\"")+"\"";}
 static string DefaultRoot=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"PACTIQO","ModusSuite");
 static string Extract(){string root=Path.Combine(Path.GetTempPath(),"PACTIQO-SETUP-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip")){if(stream==null)throw new Exception("Installation payload is missing");using(var zip=new ZipArchive(stream,ZipArchiveMode.Read)){foreach(var entry in zip.Entries){string target=Path.GetFullPath(Path.Combine(root,entry.FullName));if(!target.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("Unsafe archive path");if(entry.FullName.EndsWith("/")){Directory.CreateDirectory(target);continue;}Directory.CreateDirectory(Path.GetDirectoryName(target));using(var input=entry.Open())using(var output=new FileStream(target,FileMode.CreateNew,FileAccess.Write))input.CopyTo(output);}}}return root;}
 static string Install(string target,int port,bool demo,bool start){string temp=Extract();try{var p=new Process();p.StartInfo=new ProcessStartInfo(Path.Combine(temp,"runtime","node.exe"),Q(Path.Combine(temp,"install-suite.cjs"))+" --root "+Q(Path.GetFullPath(target))+" --port "+port+(demo?"":" --empty")+(start?" --start":""));p.StartInfo.UseShellExecute=false;p.StartInfo.CreateNoWindow=true;p.StartInfo.WindowStyle=ProcessWindowStyle.Hidden;p.StartInfo.RedirectStandardOutput=true;p.StartInfo.RedirectStandardError=true;p.StartInfo.StandardOutputEncoding=System.Text.Encoding.UTF8;p.StartInfo.StandardErrorEncoding=System.Text.Encoding.UTF8;p.Start();string stdout=p.StandardOutput.ReadToEnd(),stderr=p.StandardError.ReadToEnd();p.WaitForExit();if(p.ExitCode!=0)throw new Exception(stderr.Trim());return stdout;}finally{string safe=Path.GetFullPath(temp),parent=Path.GetFullPath(Path.GetTempPath());if(safe.StartsWith(parent,StringComparison.OrdinalIgnoreCase)&&Path.GetFileName(safe).StartsWith("PACTIQO-SETUP-"))try{Directory.Delete(safe,true);}catch{}}}
 static void Shortcut(string file,string exe,string args){Type t=Type.GetTypeFromProgID("WScript.Shell");object shell=Activator.CreateInstance(t);object link=t.InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{file});Type l=link.GetType();l.InvokeMember("TargetPath",BindingFlags.SetProperty,null,link,new object[]{exe});l.InvokeMember("Arguments",BindingFlags.SetProperty,null,link,new object[]{args});l.InvokeMember("WorkingDirectory",BindingFlags.SetProperty,null,link,new object[]{Path.GetDirectoryName(exe)});l.InvokeMember("Save",BindingFlags.InvokeMethod,null,link,null);}
 [STAThread]static int Main(string[] args){if(Array.IndexOf(args,"--silent")>=0){try{int i=Array.IndexOf(args,"--root"),j=Array.IndexOf(args,"--port");string root=i>=0?args[i+1]:DefaultRoot;int port=j>=0?int.Parse(args[j+1]):4389;Install(root,port,Array.IndexOf(args,"--empty")<0,Array.IndexOf(args,"--start")>=0);return 0;}catch(Exception e){string log=Path.Combine(Path.GetTempPath(),"PACTIQO-setup-error.txt");File.WriteAllText(log,e.Message);return 1;}}Application.EnableVisualStyles();var f=new Form{Text="Установка PACTIQO Suite",Width=720,Height=680,StartPosition=FormStartPosition.CenterScreen,Font=new Font("Segoe UI",10),FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false};var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(28)};panel.Controls.Add(new Label{Text="Один комплект. Три компонента.",Width=650,Height=50,Font=new Font("Segoe UI",21,FontStyle.Bold)});panel.Controls.Add(new Label{Text="MODUS / Desk — обращения, CRM и работа отделов.\nАдаптер — подключения и диалоги.\nCodex CLI — обработка под учётной записью клиента.",Width=640,Height=90});panel.Controls.Add(new Label{Text="Папка установки",Width=600,Height=24});var folder=new TextBox{Text=DefaultRoot,Width=640};panel.Controls.Add(folder);var demo=new CheckBox{Text="Добавить 20 учебных ситуаций организаторов",Checked=true,Width=640,Height=32};var start=new CheckBox{Text="Запустить компоненты после установки в фоне",Checked=true,Width=640,Height=32};var auto=new CheckBox{Text="Запускать комплект при входе этого пользователя Windows",Checked=false,Width=640,Height=32};panel.Controls.Add(demo);panel.Controls.Add(start);panel.Controls.Add(auto);var note=new Label{Text="Вход в Codex, Bitrix24 и каналы выполняется отдельно под аккаунтами клиента. Обработка Codex требует сети и доступного лимита аккаунта. Данные сохраняются при обновлении.",Width=640,Height=65};panel.Controls.Add(note);var b=new Button{Text="Установить комплект",Width=640,Height=42};panel.Controls.Add(b);bool installed=false;b.Click+=async(s,e)=>{if(installed){f.Close();return;}b.Enabled=false;folder.Enabled=false;demo.Enabled=false;start.Enabled=false;auto.Enabled=false;string root=folder.Text;bool d=demo.Checked,st=start.Checked,at=auto.Checked;note.Text="Проверяем файлы и устанавливаем компоненты. Это может занять несколько минут.";try{await Task.Run(()=>Install(root,4389,d,st));string exe=Path.Combine(Path.GetFullPath(root),"PACTIQO.exe");Shortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"PACTIQO MODUS.lnk"),exe,"--open");Shortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"PACTIQO Управление.lnk"),exe,"--manage");if(at)Shortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Startup),"PACTIQO Suite.lnk"),exe,"--background");note.Text="Установка проверена. Откройте PACTIQO MODUS с рабочего стола. Для входа Codex и локальных паролей используйте «PACTIQO Управление».";b.Text="Закрыть";b.Enabled=true;installed=true;}catch(Exception ex){note.Text="Установка не завершена: "+ex.Message;b.Enabled=true;folder.Enabled=true;demo.Enabled=true;start.Enabled=true;auto.Enabled=true;}};f.Controls.Add(panel);Application.Run(f);return 0;}
}
